package com.hoopr.vehicle;

import com.hoopr.admin.AdminAccess;
import com.hoopr.auth.AuthService;
import com.hoopr.ride.RideFailure;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Private documents are never returned by public ride or vehicle endpoints. */
@Service
public class DriverVerificationService {
 private final JdbcTemplate db; private final AuthService auth; private final AdminAccess access; private final Clock clock; private final boolean required;
 public DriverVerificationService(JdbcTemplate db,AuthService auth,AdminAccess access,Clock clock,@Value("${hoopr.driver-verification.required:true}") boolean required){this.db=db;this.auth=auth;this.access=access;this.clock=clock;this.required=required;}
 private LocalDate today(){return LocalDate.now(clock.withZone(ZoneId.of("Asia/Kolkata")));}
 private void owner(UUID actor,UUID vehicle){auth.profile(actor);if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM vehicles WHERE id=? AND driver_id=?)",Boolean.class,vehicle,actor)))throw new RideFailure(404,"Vehicle not found.");}
 private void lock(UUID vehicle){db.queryForObject("SELECT id FROM vehicles WHERE id=? FOR UPDATE",UUID.class,vehicle);db.update("INSERT INTO driver_vehicle_verifications(vehicle_id) VALUES(?) ON CONFLICT DO NOTHING",vehicle);db.queryForObject("SELECT vehicle_id FROM driver_vehicle_verifications WHERE vehicle_id=? FOR UPDATE",UUID.class,vehicle);}
 public record View(UUID vehicleId,String status,long revision,String licenceNumber,LocalDate licenceExpiry,String insuranceNumber,LocalDate insuranceExpiry,String reviewReason,List<String> documents){}
 private View view(UUID id){var rows=db.query("SELECT * FROM driver_vehicle_verifications WHERE vehicle_id=?",(r,n)->new View(id,r.getString("status"),r.getLong("revision"),r.getString("licence_number"),r.getObject("licence_expiry",LocalDate.class),r.getString("insurance_number"),r.getObject("insurance_expiry",LocalDate.class),r.getString("review_reason"),db.queryForList("SELECT kind FROM driver_vehicle_documents WHERE vehicle_id=? ORDER BY kind",String.class,id)),id);return rows.isEmpty()?new View(id,"DRAFT",0,null,null,null,null,null,List.of()):rows.getFirst();}
 @Transactional(readOnly=true) public View mine(UUID actor,UUID vehicle){owner(actor,vehicle);return view(vehicle);}
 public record Input(String licenceNumber,LocalDate licenceExpiry,String insuranceNumber,LocalDate insuranceExpiry){}
 private void valid(Input body){if(body.licenceNumber()==null||!body.licenceNumber().strip().matches("[A-Za-z0-9 /-]{5,80}")||body.insuranceNumber()==null||!body.insuranceNumber().strip().matches("[A-Za-z0-9 /-]{5,100}"))throw new RideFailure(400,"Enter valid licence and insurance policy numbers.");if(body.licenceExpiry()==null||body.insuranceExpiry()==null||body.licenceExpiry().isBefore(today())||body.insuranceExpiry().isBefore(today()))throw new RideFailure(400,"Driving licence and insurance must not be expired.");}
 @Transactional public View save(UUID actor,UUID vehicle,Input body){owner(actor,vehicle);valid(body);lock(vehicle);db.update("UPDATE driver_vehicle_verifications SET licence_number=?,licence_expiry=?,insurance_number=?,insurance_expiry=?,status='DRAFT',review_reason=NULL,reviewed_by=NULL,reviewed_at=NULL,revision=revision+1,updated_at=now() WHERE vehicle_id=?",body.licenceNumber().strip(),body.licenceExpiry(),body.insuranceNumber().strip(),body.insuranceExpiry(),vehicle);return view(vehicle);}
 @Transactional public View upload(UUID actor,UUID vehicle,String kind,String content){owner(actor,vehicle);if(!Set.of("LICENCE","RC","INSURANCE").contains(kind))throw new RideFailure(400,"Unsupported document type.");byte[] data;try{if(content==null||content.length()>2796204)throw new IllegalArgumentException();data=Base64.getDecoder().decode(content);}catch(IllegalArgumentException e){throw new RideFailure(400,"Choose a PDF, JPG or PNG of at most 2 MB.");}if(data.length<8||data.length>2097152)throw new RideFailure(400,"Choose a PDF, JPG or PNG of at most 2 MB.");String type=mediaType(data);lock(vehicle);db.update("INSERT INTO driver_vehicle_documents(vehicle_id,kind,media_type,content) VALUES(?,?,?,?) ON CONFLICT(vehicle_id,kind) DO UPDATE SET media_type=EXCLUDED.media_type,content=EXCLUDED.content",vehicle,kind,type,data);db.update("UPDATE driver_vehicle_verifications SET status='DRAFT',review_reason=NULL,reviewed_by=NULL,reviewed_at=NULL,revision=revision+1,updated_at=now() WHERE vehicle_id=?",vehicle);return view(vehicle);}
 static String mediaType(byte[] b){if(b.length>=8&&b[0]==(byte)0x89&&b[1]=='P'&&b[2]=='N'&&b[3]=='G'&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)return "image/png";if(b.length>=3&&b[0]==(byte)0xff&&b[1]==(byte)0xd8&&b[2]==(byte)0xff)return "image/jpeg";if(b.length>=5&&b[0]=='%'&&b[1]=='P'&&b[2]=='D'&&b[3]=='F'&&b[4]=='-')return "application/pdf";throw new RideFailure(400,"The file content must be PDF, JPG or PNG.");}
 @Transactional public View submit(UUID actor,UUID vehicle){owner(actor,vehicle);lock(vehicle);View v=view(vehicle);valid(new Input(v.licenceNumber(),v.licenceExpiry(),v.insuranceNumber(),v.insuranceExpiry()));if(v.documents().size()!=3)throw new RideFailure(400,"Upload driving licence, vehicle RC and insurance before submitting.");if(v.status().equals("APPROVED"))return v;db.update("UPDATE driver_vehicle_verifications SET status='PENDING',review_reason=NULL,reviewed_by=NULL,reviewed_at=NULL,revision=revision+1,updated_at=now() WHERE vehicle_id=?",vehicle);return view(vehicle);}
 @Transactional(readOnly=true) public List<Map<String,Object>> queue(UUID actor){access.require(actor,"VEHICLE_STATUS");return db.queryForList("SELECT x.vehicle_id,x.status,x.revision,x.updated_at,v.make,v.model,v.registration_number,u.email FROM driver_vehicle_verifications x JOIN vehicles v ON v.id=x.vehicle_id JOIN users u ON u.id=v.driver_id WHERE x.status IN ('PENDING','APPROVED','REJECTED') ORDER BY x.updated_at DESC LIMIT 100");}
 @Transactional(readOnly=true) public View reviewDetails(UUID actor,UUID vehicle){access.require(actor,"VEHICLE_STATUS");return view(vehicle);}
 public record Document(String mediaType,byte[] content){}
 @Transactional public Document document(UUID actor,UUID vehicle,String kind,boolean admin){if(admin){access.require(actor,"VEHICLE_STATUS");UUID target=db.queryForObject("SELECT driver_id FROM vehicles WHERE id=?",UUID.class,vehicle);access.audit(actor,target,"DOCUMENT_VIEW","VEHICLE",vehicle.toString(),view(vehicle).status(),view(vehicle).status(),"Reviewed private "+kind+" document");}else owner(actor,vehicle);return db.query("SELECT media_type,content FROM driver_vehicle_documents WHERE vehicle_id=? AND kind=?",(r,n)->new Document(r.getString(1),r.getBytes(2)),vehicle,kind).stream().findFirst().orElseThrow(()->new RideFailure(404,"Document not found."));}
 @Transactional public View review(UUID actor,UUID vehicle,String decision,long revision,String reason){access.require(actor,"VEHICLE_STATUS");AdminAccess.reason(reason);if(!Set.of("APPROVED","REJECTED").contains(decision))throw new RideFailure(400,"Choose approve or reject.");lock(vehicle);UUID target=db.queryForObject("SELECT driver_id FROM vehicles WHERE id=?",UUID.class,vehicle);if(actor.equals(target))throw new RideFailure(403,"You cannot review your own documents.");View v=view(vehicle);if(v.revision()!=revision||!v.status().equals("PENDING"))throw new RideFailure(409,"This submission changed. Refresh before reviewing.");if(decision.equals("APPROVED"))valid(new Input(v.licenceNumber(),v.licenceExpiry(),v.insuranceNumber(),v.insuranceExpiry()));if(v.documents().size()!=3)throw new RideFailure(409,"The submission is incomplete.");db.update("UPDATE driver_vehicle_verifications SET status=?,review_reason=?,reviewed_by=?,reviewed_at=now(),revision=revision+1,updated_at=now() WHERE vehicle_id=?",decision,reason.strip(),actor,vehicle);access.audit(actor,target,"DRIVER_DOCUMENT_REVIEW","VEHICLE",vehicle.toString(),v.status(),decision,reason);return view(vehicle);}
 @Transactional public void requireApproved(UUID driver,UUID vehicle){if(!required)return;if(vehicle==null)throw new RideFailure(403,"Select a verified vehicle. Driving licence, RC and insurance approval is required before offering rides.");owner(driver,vehicle);lock(vehicle);View v=view(vehicle);if(!v.status().equals("APPROVED")||v.licenceExpiry()==null||v.insuranceExpiry()==null||v.licenceExpiry().isBefore(today())||v.insuranceExpiry().isBefore(today()))throw new RideFailure(403,"Driving licence, vehicle RC and insurance must be approved and unexpired before offering this ride.");}
}
